package cn.lxz.sweb.message;

import com.taobao.metamorphosis.Message;
import com.taobao.metamorphosis.client.producer.MessageProducer;
import com.taobao.metamorphosis.client.producer.SendMessageCallback;
import com.taobao.metamorphosis.client.producer.SendResult;
import com.taobao.metamorphosis.exception.MetaClientException;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.ObjectOutputStream;
import java.util.concurrent.Semaphore;
import java.util.concurrent.TimeUnit;

/**
 * Created by jihua.li on 2016/6/26.
 * 消息创建
 */
public class Publisher {

     private static Logger logger= LoggerFactory.getLogger(Publisher.class);

    /**
     * 同步发送消息
     * @param topic 消息主题
     * @param message 消息内容
     * @return  消息id,系统唯一
     */
    public static String syncSendMessage(String topic,Object message){
        return syncSendMessage(topic,message,3,TimeUnit.SECONDS);
    }

    /**
     * 同步发送消息
     * @param topic 消息主题
     * @param message 消息内容
     * @param timeLimit 时间要求 默认 2s
     * @param unit  时间单位
     * @return  消息id 系统唯一
     */
    public static String syncSendMessage(String topic,Object message,long timeLimit, TimeUnit unit){
        SingleMetaMessageSession  sessionFactory =SingleMetaMessageSession.getInstance();
        MessageProducer producer = sessionFactory.getSingleProducer();
        producer.setDefaultTopic("*");
        Message msg=new Message(topic,toByteArray(message));
        String messageId=null;
        try {
            SendResult sendResult=producer.sendMessage(msg,timeLimit,unit);
            if(sendResult.isSuccess()){
                messageId=String.valueOf(msg.getId());
                logger.info("同步发送消息成功了，消息主题：{}，BrokerId:{},保存在第{}分区",topic,sendResult.getPartition().getBrokerId(),sendResult.getPartition().getPartition());
            }else{
                logger.info("同步发送消息失败了，失败原因：{}",sendResult.getErrorMessage());
            }
        } catch (MetaClientException e) {
            logger.error("同步发送消息，客户端连接异常:{}",e.getLocalizedMessage());
        } catch (InterruptedException e) {
            logger.error("同步发送消息，中断异常:{}",e.getLocalizedMessage());
        }
        return messageId;
    }

    /**
     * 异步发送消息，
     * @param topic 消息主题
     * @param message 消息内容
     * @param callback 回调方法
     */
    public static void asyncSendMessage(String topic, Object message,SendMessageCallback callback){
        asyncSendMessage(topic,message,3,TimeUnit.SECONDS,callback);
    }

    /**
     * 异步发送消息，不设置时间
     * @param topic 消息主题
     * @param message 消息内容
     */
    public static void asyncSendMessage(String topic, Object message){
         asyncSendMessage(topic,message,3,TimeUnit.SECONDS,new CallBackHandle());
    }
